package com.astra.antiqua.data.content

import com.astra.antiqua.domain.ZodiacSign
import com.astra.antiqua.model.ClassicalPlanet
import java.io.ByteArrayInputStream
import java.io.File
import java.io.IOException
import java.io.InputStream
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * `shared/content/planet-in-sign.json` is generated by web and read in place
 * (see `app/build.gradle.kts`'s `sourceSets.main.assets.srcDir`), so this
 * test reaches it the same way `OracleDecreeKeyCoverageTest` used to reach
 * `oracle_decrees.json`: a relative path off the Gradle `Test` task's working
 * directory, which is the module directory (`app/`).
 */
class PlacementContentStoreTest {

    private val assetFile = File("../../shared/content/planet-in-sign.json")

    private fun realStore() = PlacementContentStore { assetFile.inputStream() }

    @Test
    fun `every planet by sign combination resolves to non-blank universal text`() {
        assertTrue("Expected to find ${assetFile.path}", assetFile.exists())
        val store = realStore()

        for (planet in ClassicalPlanet.values()) {
            for (sign in ZodiacSign.values()) {
                val text = store.textFor(planet, sign)
                assertTrue("Blank placement text for $planet/$sign", text.isNotBlank())
            }
        }
    }

    @Test
    fun `the asset is parsed exactly once no matter how many lookups are made`() {
        var openCount = 0
        val store = PlacementContentStore {
            openCount++
            assetFile.inputStream()
        }

        // Multiple lookups, across multiple planets and signs.
        store.textFor(ClassicalPlanet.SUN, ZodiacSign.ARIES)
        store.textFor(ClassicalPlanet.SUN, ZodiacSign.LEO)
        store.textFor(ClassicalPlanet.MOON, ZodiacSign.CANCER)
        store.textFor(ClassicalPlanet.SATURN, ZodiacSign.CAPRICORN)

        assertEquals("openStream should run once per store instance, not once per lookup", 1, openCount)
    }

    @Test
    fun `an IO failure surfaces as ContentLoadException Io`() {
        val store = PlacementContentStore {
            object : InputStream() {
                override fun read(): Int = throw IOException("disk unavailable")
            }
        }

        assertThrows(ContentLoadException.Io::class.java) {
            store.textFor(ClassicalPlanet.SUN, ZodiacSign.ARIES)
        }
    }

    @Test
    fun `malformed JSON surfaces as ContentLoadException Malformed`() {
        val store = PlacementContentStore { ByteArrayInputStream("{ not valid json".toByteArray()) }

        assertThrows(ContentLoadException.Malformed::class.java) {
            store.textFor(ClassicalPlanet.SUN, ZodiacSign.ARIES)
        }
    }

    @Test
    fun `a missing planet key surfaces as ContentLoadException MissingKey`() {
        // Valid JSON, but with no "sun" entry at all.
        val store = PlacementContentStore { ByteArrayInputStream("""{"moon": {"Aries": "text"}}""".toByteArray()) }

        assertThrows(ContentLoadException.MissingKey::class.java) {
            store.textFor(ClassicalPlanet.SUN, ZodiacSign.ARIES)
        }
    }

    @Test
    fun `a missing sign key surfaces as ContentLoadException MissingKey`() {
        // "sun" is present, but has no "Aries" entry.
        val store = PlacementContentStore { ByteArrayInputStream("""{"sun": {"Taurus": "text"}}""".toByteArray()) }

        assertThrows(ContentLoadException.MissingKey::class.java) {
            store.textFor(ClassicalPlanet.SUN, ZodiacSign.ARIES)
        }
    }
}
